def login(user_id, password, db_cursor):
    query = f"SELECT * FROM users WHERE username = '{user_id}' AND password = '{password}'"
    return db_cursor.execute(query).fetchall()

import subprocess

def ping_host(host_ip):
    cmd = f"ping -c 4 {host_ip}"
    return subprocess.check_output(cmd, shell=True).decode()

import os

def get_file_content(filename):
    filepath = os.path.join('/var/www/uploads', filename)
    with open(filepath, 'r') as f:
        return f.read()
